/*
 * A063821  Growth series for fundamental group of orientable closed surface
 *          of genus 11.
 * https://oeis.org/A063821
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   Generated by the rational function
 *            (1+x)*(1-x^22)/(1-43*x+43*x^22-x^23) Recurrence: a(0)=1,
 *            a(1)=44, for n≥2 a(n) = 43*a(n-1) - 43*a(n-22) + a(n-23)
 *            together with the inhomogeneous terms a(n) += 1 for n=0,1 and
 *            a(n) -= 1 for n=22,23
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 5, u64 n <= 11, u128 n <= 23,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *arr = NULL;
    static idx_t cap = 0;

    /* Initialise on first call */
    if (arr == NULL) {
        cap = 1;
        arr = (seq_t*)malloc(cap * sizeof(seq_t));
        if (!arr) exit(1);
        arr[0] = (seq_t)1;  /* a(0) */
    }

    /* Grow array until it covers n */
    while (n >= cap) {
        size_t newcap = (size_t)cap * 2;
        if (newcap == 0) newcap = 1;   /* just in case */
        seq_t *tmp = (seq_t*)realloc(arr, newcap * sizeof(seq_t));
        if (!tmp) exit(1);
        arr = tmp;

        /* Compute new entries */
        for (idx_t i = cap; i < newcap; ++i) {
            seq_t val = 0;
            if (i > 0)                val += (seq_t)43 * arr[i-1];
            if (i >= 22)              val -= (seq_t)43 * arr[i-22];
            if (i >= 23)              val += arr[i-23];
            if (i == 0 || i == 1)     val += (seq_t)1;
            if (i == 22 || i == 23)   val -= (seq_t)1;
            arr[i] = val;
        }
        cap = newcap;
    }

    return arr[n];
}
